function longestCommonSubsequence(s1, s2) {
  const memo = new Map();

  function lcs(i1, i2) {
    if (i1 === s1.length || i2 === s2.length) {
      return 0;
    }

    const key = `${i1},${i2}`;
    if (memo.has(key)) {
      return memo.get(key);
    }

    let result;
    if (s1[i1] === s2[i2]) {
      result = 1 + lcs(i1 + 1, i2 + 1);
    } else {
      result = Math.max(lcs(i1 + 1, i2), lcs(i1, i2 + 1));
    }
    memo.set(key, result);
    return result;
  }

  return lcs(0, 0);
}

